from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_CELL = re.compile(r":?-+:?")
_UNESCAPED_PIPE = re.compile(r"(?<!\\)\|")


def _cell_text(value: object) -> str:
    """Convert one cell value to its (escaped) text."""
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    """Pad ``text`` to ``width`` according to ``alignment``."""
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _table_line(cells: list[str], widths: list[int], align: list[str | None]) -> str:
    padded = [_pad(cell, width, alignment) for cell, width, alignment in zip(cells, widths, align)]
    return "| " + " | ".join(padded) + " |"


def _delimiter_line(widths: list[int], align: list[str | None]) -> str:
    cells = []
    for width, alignment in zip(widths, align):
        if alignment == "left":
            cell = ":" + "-" * (width - 1)
        elif alignment == "right":
            cell = "-" * (width - 1) + ":"
        elif alignment == "center":
            cell = ":" + "-" * (width - 2) + ":"
        else:
            cell = "-" * width
        cells.append(cell)
    return "| " + " | ".join(cells) + " |"


def _split_line(line: str) -> list[str]:
    """Split one table line into stripped, unescaped cells."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    return [cell.strip().replace("\\|", "|") for cell in _UNESCAPED_PIPE.split(line)]


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)
    if align is None:
        alignments: list[str | None] = [None] * columns
    else:
        try:
            alignments = list(align)
        except TypeError:
            raise ValueError("align must be a list of alignments") from None
        if len(alignments) != columns:
            raise ValueError("align must have one entry per column")
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    header_cells = [_cell_text(value) for value in header]
    rows_cells = []
    for row in rows:
        if len(row) > columns:
            raise ValueError("row has more cells than the header")
        rows_cells.append(
            [_cell_text(value) for value in row] + [""] * (columns - len(row))
        )

    widths = []
    for column in range(columns):
        width = len(header_cells[column])
        for row in rows_cells:
            width = max(width, len(row[column]))
        widths.append(max(3, width))

    lines = [_table_line(header_cells, widths, alignments)]
    lines.append(_delimiter_line(widths, alignments))
    lines.extend(_table_line(row, widths, alignments) for row in rows_cells)
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("not a table: fewer than two lines")

    header = _split_line(lines[0])
    delimiter = _split_line(lines[1])
    if len(delimiter) != len(header):
        raise ValueError("delimiter line has a different number of cells than the header")

    alignments: list[str | None] = []
    for cell in delimiter:
        if _DELIMITER_CELL.fullmatch(cell) is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        if cell.startswith(":") and cell.endswith(":"):
            alignments.append("center")
        elif cell.startswith(":"):
            alignments.append("left")
        elif cell.endswith(":"):
            alignments.append("right")
        else:
            alignments.append(None)

    rows = []
    for line in lines[2:]:
        cells = _split_line(line)
        if len(cells) != len(header):
            raise ValueError("row has a different number of cells than the header")
        rows.append(cells)

    return header, rows, alignments

